# Caddyfile
{{domain}} {
    encode gzip zstd
    log {
        output file /var/log/caddy/{{domain}}.log
        format json
    }

    handle_path /api/* {
        reverse_proxy {{upstream}} {
            header_up X-Real-IP {remote_host}
            header_up X-Forwarded-Proto {scheme}
        }
    }

    handle {
        root * /var/www/{{domain}}
        try_files {path} /index.html
        file_server
    }
}
